PREFIX bball: <http://www.ics.forth.gr/isl/Basketball#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?action ?totalRebounds ?playerName ?quarter ?clock ?homeScore ?roadScore ?order WHERE {
  ?game bball:hasSeason ?season ; bball:hasCode "333" ; bball:hasPlayByPlayAction ?action .
  ?season bball:hasCode "E2023" .
  ?player rdfs:label ?playerName .
  FILTER(regex(str(?playerName), '(^|[^A-Za-z0-9])Walter Tavares([^A-Za-z0-9]|$)', 'i'))
  VALUES ?reboundType { bball:OffensiveRebound bball:DefensiveRebound }
  ?action rdf:type ?reboundType ; bball:actionPlayer ?player ; bball:hasPlayByPlaySequence ?order .
  OPTIONAL { ?action bball:quarter ?quarter ; bball:clock ?clock . }
  OPTIONAL { ?action bball:runningHomeTeamScore ?homeScore ; bball:runningRoadTeamScore ?roadScore . }
  {
    SELECT ?game ?player (COUNT(DISTINCT ?subAction) AS ?totalRebounds) WHERE {
      ?game bball:hasSeason ?subSeason ; bball:hasCode "333" ; bball:hasPlayByPlayAction ?subAction .
      ?subSeason bball:hasCode "E2023" .
      ?player rdfs:label ?subPlayerName .
      FILTER(regex(str(?subPlayerName), '(^|[^A-Za-z0-9])Walter Tavares([^A-Za-z0-9]|$)', 'i'))
      VALUES ?subReboundType { bball:OffensiveRebound bball:DefensiveRebound }
      ?subAction rdf:type ?subReboundType ; bball:actionPlayer ?player .
    } GROUP BY ?game ?player
  }
} ORDER BY xsd:integer(?order) LIMIT 100

PREFIX bball: <http://www.ics.forth.gr/isl/Basketball#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (SUM(?madeValue) AS ?made) (COUNT(?action) AS ?attempts) (100.0 * SUM(?madeValue) / COUNT(?action) AS ?percentage)
WHERE {
  ?game a bball:Game ; 
        bball:hasCode "333" ; 
        bball:hasSeason ?season ; 
        bball:hasPlayByPlayAction ?action .
  ?season bball:hasCode "E2023" .
  ?player rdfs:label ?playerName .
  FILTER(regex(str(?playerName), '(^|[^A-Za-z0-9])Kendrick Nunn([^A-Za-z0-9]|$)', 'i'))
  ?action bball:actionPlayer ?player .
  VALUES ?actionType { bball:ThreePointShotMade bball:ThreePointShotMissed }
  ?action rdf:type ?actionType .
  BIND(IF(?actionType = bball:ThreePointShotMade, 1, 0) AS ?madeValue)
} LIMIT 1

PREFIX bball: <http://www.ics.forth.gr/isl/Basketball#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?action ?playerName ?receiverName ?points ?quarter ?clock ?homeScore ?roadScore ?order WHERE {
  ?game a bball:Game ;
        bball:hasSeason ?season ;
        bball:hasCode ?gameCode ;
        bball:hasPlayByPlayAction ?action .
  ?season bball:hasCode ?seasonCode .
  FILTER(str(?seasonCode) = "E2023")
  FILTER(str(?gameCode) = "333")

  ?action rdf:type bball:Assist ;
          bball:actionPlayer ?assistingPlayer .
  ?assistingPlayer rdfs:label ?playerName .
  FILTER(regex(str(?playerName), '(^|[^A-Za-z0-9])Kostas Sloukas([^A-Za-z0-9]|$)', 'i'))

  VALUES ?madeShotType { bball:TwoPointShotMade bball:ThreePointShotMade bball:FreeThrowMade }
  ?shot rdf:type ?madeShotType ;
        bball:hasAssist ?action ;
        bball:actionPlayer ?receivingPlayer .
  ?receivingPlayer rdfs:label ?receiverName .
  FILTER(regex(str(?receiverName), '(^|[^A-Za-z0-9])Kendrick Nunn([^A-Za-z0-9]|$)', 'i'))

  OPTIONAL { ?shot bball:pointsAwarded ?points . }
  OPTIONAL { ?action bball:quarter ?quarter . }
  OPTIONAL { ?action bball:clock ?clock . }
  OPTIONAL { ?action bball:runningHomeTeamScore ?homeScore ; bball:runningRoadTeamScore ?roadScore . }
  OPTIONAL { ?action bball:hasPlayByPlaySequence ?order . }
}
ORDER BY xsd:integer(?order)
LIMIT 100
